// Tính ngày hôm nay theo múi giờ Asia/Ho_Chi_Minh
const vnNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' }));

const yyyy = vnNow.getFullYear();
const mm = String(vnNow.getMonth() + 1).padStart(2, '0');
const dd = String(vnNow.getDate()).padStart(2, '0');
const HH = String(vnNow.getHours()).padStart(2, '0');
const min = String(vnNow.getMinutes()).padStart(2, '0');

return [{ json: {
  reportDate: `${yyyy}-${mm}-${dd}`,
  reportTime: `${HH}:${min}`
} }];

const reportDate = $('Tính Ngày Hôm Nay').first().json.reportDate;

const token = $env.META_ACCESS_TOKEN;
if (!token) {
  throw new Error('Missing META_ACCESS_TOKEN environment variable.');
}

const timeRange = encodeURIComponent(JSON.stringify({ since: reportDate, until: reportDate }));
const url = `https://graph.facebook.com/v19.0/act_303484773737553/insights?time_range=${timeRange}&level=ad&fields=ad_id,ad_name,campaign_name,spend,reach,clicks,inline_link_clicks,impressions,frequency,actions,video_view,video_p25_watched_actions,video_p50_watched_actions,video_p75_watched_actions,video_p95_watched_actions,video_thruplay_watched_actions,outbound_clicks,date_start&limit=500`;
let success = false;
let attempts = 0;
let responseData = {};

while (!success && attempts < 3) {
  attempts++;
  try {
    responseData = await this.helpers.httpRequest({
      method: 'GET',
      url,
      json: true,
      headers: { Authorization: `Bearer ${token}` }
    });
    success = true;
  } catch (error) {
    const metaErrorBody = error.response?.data
      ? JSON.stringify(error.response.data) : '';
    const errMsg = (error.message || '') + ' ' + metaErrorBody;

    const isRateLimitError = errMsg.includes('Application request limit reached');
    const networkErrorPatterns = [
      'Client network socket disconnected',
      'ECONNRESET', 'ETIMEDOUT', 'socket hang up'
    ];
    const isNetworkError = networkErrorPatterns.some(p =>
      errMsg.toLowerCase().includes(p.toLowerCase())
    );

    if (isRateLimitError) {
      if (attempts >= 3) throw new Error('Rate limit. Vẫn lỗi sau 3 lần retry.');
      const wait = Math.floor(Math.random() * 60000) + 60000;
      await new Promise(r => setTimeout(r, wait));
    } else if (isNetworkError) {
      if (attempts >= 3) throw new Error('Lỗi mạng tạm thời. Vẫn lỗi sau 3 lần retry.');
      await new Promise(r => setTimeout(r, attempts * 3000));
    } else {
      throw new Error('Meta API Error: ' + JSON.stringify(error.response?.data || error.message, null, 2));
    }
  }
}

return [{ json: responseData }];

const reportDate = $('Tính Ngày Hôm Nay').first().json.reportDate;
const reportTime = $('Tính Ngày Hôm Nay').first().json.reportTime;
const insights = $input.first().json.data || [];

if (insights.length === 0) {
  return [{ json: {
    reportDate,
    reportTime,
    hasData: false,
    campaignCount: 0,
    totals: null,
    kpis: null,
    message: [
      `📊 *BÁO CÁO META ADS — HÔM NAY*`,
      `📅 Ngày: ${reportDate}  ⏰ ${reportTime} VN`,
      ``,
      `⚠️ Chưa có dữ liệu từ Meta API cho hôm nay.`,
      `💡 Có thể campaign chưa chạy hoặc spend = 0.`,
    ].join('\n')
  }}];
}

// === Helper parse an toàn ===
const toInt = (v) => parseInt(v, 10) || 0;
const toFloat = (v) => parseFloat(v) || 0;

// === Aggregate Raw Metrics ===
const totals = {
  spend:       0,
  reach:       0,
  luotHienThi: 0,
  click:       0,   // Link Click (inline_link_clicks)
  clickAll:    0,   // Total Clicks (clicks)
  mess:        0,
};

for (const row of insights) {
  totals.spend       += toFloat(row.spend);
  totals.reach       += toInt(row.reach);
  totals.luotHienThi += toInt(row.impressions);
  totals.click       += toInt(row.inline_link_clicks);
  totals.clickAll    += toInt(row.clicks);

  if (row.actions) {
    const messAction = row.actions.find(
      a => a.action_type === 'onsite_conversion.messaging_conversation_started_7d'
    );
    totals.mess += messAction ? toInt(messAction.value) : 0;
  }
}

// === Tính KPI từ Raw Metrics (không dùng cột công thức) ===
const kpis = {
  cpm:         totals.luotHienThi > 0
    ? Math.round(totals.spend / totals.luotHienThi * 1000) : null,
  ctrLink:     totals.luotHienThi > 0
    ? parseFloat((totals.click / totals.luotHienThi * 100).toFixed(2)) : null,
  ctrAll:      totals.luotHienThi > 0
    ? parseFloat((totals.clickAll / totals.luotHienThi * 100).toFixed(2)) : null,
  cpc:         totals.click > 0
    ? Math.round(totals.spend / totals.click) : null,
  costPerMess: totals.mess > 0
    ? Math.round(totals.spend / totals.mess) : null,
};

// === Format Telegram ===
const fmt = (n) => Math.round(n).toLocaleString('vi-VN');
const fmtMoney = (n) => n === null ? 'N/A' : fmt(n) + 'đ';
const fmtPct = (n) => n === null ? 'N/A' : n.toFixed(2) + '%';

const message = [
  `📊 *BÁO CÁO META ADS — HÔM NAY*`,
  `📅 Ngày: ${reportDate}  ⏰ ${reportTime} VN`,
  ``,
  `💰 Chi tiêu: *${fmt(totals.spend)}đ*`,
  `📩 Mess: *${totals.mess}*`,
  `💵 Cost/Mess: *${fmtMoney(kpis.costPerMess)}*`,
  `📈 CPM: *${fmtMoney(kpis.cpm)}* — 👥 Tiếp cận: *${fmt(totals.reach)}*`,
  `📈 CTR: *${fmtPct(kpis.ctrLink)}*`,
  `📈 CPC: *${fmtMoney(kpis.cpc)}* — 🖱️ Click: *${totals.click}*`,
].join('\n');

return [{ json: {
  reportDate,
  reportTime,
  hasData: true,
  campaignCount: insights.length,
  totals,
  kpis,
  message
} }];
